// Looks 2 to 5 of the Upcoming events mystery card (look 1 = Signal lives in HackathonTeaser.jsx).
//   2 = Terminal   3 = Dossier   4 = Blueprint   5 = Vault
// Each look has its own colours for hackathon / workshop / online (the words and the detail boxes come from teaserCore.jsx).
// You do not edit this file: the look is picked by itself (see DESIGNS in site/upcomingConfig.js).
import { Icon } from './Icons';
import { Actions, FieldValue } from './teaserCore';
import PosterStage, { HAS_POSTERS } from './PosterStage';
import { CardTitle } from './NameReveal';
import './TeaserCards.css';

/* a small picture that tells the kind of event: </> for hackathon, a wrench for workshop, a globe for online */
function Motif({ type, size = 30 }) {
  if (type === 'workshop') {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
        <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z" />
      </svg>
    );
  }
  if (type === 'online') return <Icon.Globe size={size} />;
  return <Icon.Code size={size} />;
}
const Lock = ({ size = 16 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <rect x="3" y="11" width="18" height="11" rx="2" /><path d="M7 11V7a5 5 0 0 1 10 0v4" />
  </svg>
);

/* the countdown tiles (asleep with "--" until a start date is set) */
function Clock({ t }) {
  if (t.live) return <div className="s-live tc-live"><i /> It&apos;s live</div>;
  return (
    <div className="tc-clock">
      <span className="tc-clock-l">{t.counting ? 'Starts in' : t.copy.wait}</span>
      <div
        className={`tc-cells ${t.waiting ? 'is-idle' : ''}`}
        role={t.counting ? 'timer' : 'group'}
        aria-label={t.counting ? `Starts in ${t.c.d} days ${t.c.h} hours ${t.c.m} minutes` : 'Timer not started yet'}
      >
        {t.cells.map(([name, v]) => (
          <div className="tc-cell" key={name}>
            <b key={v}>{typeof v === 'number' ? String(v).padStart(2, '0') : v}</b>
            <span>{name}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* the progress line */
function Prog({ t }) {
  return (
    <div className="tc-prog" role="progressbar" aria-label="Compiling" aria-valuemin={0} aria-valuemax={100} aria-valuenow={t.shown}>
      <span>{t.status}</span>
      <div className="tc-track"><i style={{ width: `${t.shown}%` }} /></div>
      <span>{t.shown}%</span>
    </div>
  );
}

/* one detail box. The look decides how it is drawn, this keeps the same content in all of them. */
const Field = ({ f, label }) => (
  <div className={`tc-f is-${f.state}`}>
    <span className="tc-k">{label || f.k}</span>
    <b className="tc-v"><FieldValue f={f} /></b>
  </div>
);

/* ---------- 2. terminal ---------- */
function Terminal({ t }) {
  const { copy } = t;
  const left = t.cells.map(([n, v]) => `${typeof v === 'number' ? String(v).padStart(2, '0') : v}${n[0].toLowerCase()}`).join(' ');
  return (
    <article className={`tc tc-term t-${t.type} is-${t.phase}`} aria-label={t.label}>
      <div className="tc-bar" aria-hidden="true">
        <i /><i /><i />
        <span>sipna@coders:~/{t.type}$ ./reveal</span>
        <em>{copy.tag}</em>
      </div>
      <div className="tc-term-body">
        <p className="tc-prompt" aria-hidden="true"><b>$</b> cat event.txt<span className="tc-caret" /></p>
        <PosterStage kind="card" onlyWithPoster>
          <div className="ps-ph" aria-hidden="true"><b>?</b><span>poster.jpg // locked</span></div>
        </PosterStage>
        <CardTitle t={t} className="tc-title" />
        <p className="tc-lede">{copy.lede}</p>
        <p className="tc-desc">{copy.desc}</p>

        {t.live ? (
          <div className="s-live tc-live"><i /> It&apos;s live</div>
        ) : (
          <div className="tc-tmin" role={t.counting ? 'timer' : 'group'} aria-label={t.counting ? `Starts in ${t.c.d} days ${t.c.h} hours ${t.c.m} minutes` : 'Timer not started yet'}>
            <span>{t.counting ? 'starts_in' : 'T-minus'}</span>
            <b className={t.waiting ? 'is-idle' : ''}>{left}</b>
            {t.waiting && <em>// {copy.wait.toLowerCase()}</em>}
          </div>
        )}

        <div className="tc-kv">
          {t.fields.map((f) => <Field key={f.k} f={f} label={f.k.toLowerCase().replace(/ /g, '_')} />)}
        </div>
        <Prog t={t} />
        <Actions t={t} />
      </div>
    </article>
  );
}

/* ---------- 3. dossier ---------- */
function Dossier({ t }) {
  const { copy } = t;
  return (
    <article className={`tc tc-doss t-${t.type} is-${t.phase} ${HAS_POSTERS ? 'has-poster' : ''}`} aria-label={t.label}>
      <div className="tc-doss-tab" aria-hidden="true">Case file · {copy.noun}</div>
      <div className="tc-doss-sheet">
        <aside className="tc-doss-side">
          <PosterStage kind="card" className="ps-soft" cap={440} frameW={20} frameH={44}>
            <div className="tc-doss-photo" aria-hidden="true"><Motif type={t.type} size={34} /><b>?</b></div>
          </PosterStage>
          <span className="tc-doss-id" aria-hidden="true">NO. {t.hex.slice(0, 4)}-{t.hex.slice(6, 10)}</span>
        </aside>
        <div className="tc-doss-main">
          <span className="tc-doss-stamp" aria-hidden="true">{copy.tag}</span>
          <div className="tc-doss-flag"><i /> {copy.flag} <em>/ {copy.file}</em></div>
          <CardTitle t={t} className="tc-title" />
          <p className="tc-lede">{copy.lede}</p>
          <p className="tc-desc">{copy.desc}</p>
          <Clock t={t} />
          <div className="tc-rows">
            {t.fields.map((f) => <Field key={f.k} f={f} />)}
          </div>
          <Prog t={t} />
          <Actions t={t} />
        </div>
      </div>
    </article>
  );
}

/* ---------- 4. blueprint ---------- */
function Blueprint({ t }) {
  const { copy } = t;
  return (
    <article className={`tc tc-bp t-${t.type} is-${t.phase} ${HAS_POSTERS ? 'has-poster' : ''}`} aria-label={t.label}>
      <i className="tc-bp-c tl" aria-hidden="true" /><i className="tc-bp-c tr" aria-hidden="true" />
      <i className="tc-bp-c bl" aria-hidden="true" /><i className="tc-bp-c br" aria-hidden="true" />
      <header className="tc-bp-head" aria-hidden="true">
        <span>Sheet 01 / 01</span><span>{copy.flag}</span><span>Rev 0.1</span>
      </header>
      <div className="tc-bp-main">
        <PosterStage kind="card" cap={440}>
          <div className="tc-bp-fig" aria-hidden="true">
            <div className="tc-bp-ring"><i /><i /><i /></div>
            <div className="tc-bp-ic"><Motif type={t.type} size={44} /></div>
            <span className="tc-bp-dim"><b>Ø ???</b></span>
          </div>
        </PosterStage>
        <div className="tc-bp-txt">
          <CardTitle t={t} className="tc-title" />
          <p className="tc-lede">{copy.lede}</p>
          <p className="tc-desc">{copy.desc}</p>
          <Clock t={t} />
          <div className="tc-rows">
            {t.fields.map((f) => <Field key={f.k} f={f} />)}
          </div>
        </div>
      </div>
      <div className="tc-bp-low"><Prog t={t} /><Actions t={t} /></div>
      <footer className="tc-bp-block" aria-hidden="true">
        <span><small>Project</small>Sipna Coders Club</span>
        <span><small>Drawing</small>{copy.noun}</span>
        <span><small>Status</small>{t.shown}% drawn</span>
      </footer>
    </article>
  );
}

/* ---------- 5. vault ---------- */
function Vault({ t }) {
  const { copy } = t;
  return (
    <article className={`tc tc-vault t-${t.type} is-${t.phase}`} aria-label={t.label}>
      <PosterStage kind="card" cap={420}>
        <div className="tc-vault-dial" aria-hidden="true">
          <span className="tc-vault-ticks" />
          <span className="tc-vault-ring" />
          <span className="tc-vault-core"><Lock size={46} /></span>
          <span className="tc-vault-pin" />
        </div>
      </PosterStage>
      <div className="tc-vault-main">
        <span className="tc-vault-flag"><i /> {copy.flag}</span>
        <CardTitle t={t} className="tc-title" />
        <p className="tc-lede">{copy.lede}</p>
        <p className="tc-desc">{copy.desc}</p>
        <Clock t={t} />
        <div className="tc-tiles">
          {t.fields.map((f) => (
            <div key={f.k} className={`tc-f is-${f.state}`}>
              <span className="tc-k">{f.k}</span>
              <b className="tc-v"><FieldValue f={f} /></b>
              <span className="tc-lock" aria-hidden="true"><Lock size={14} /></span>
            </div>
          ))}
        </div>
        <Prog t={t} />
        <Actions t={t} />
      </div>
    </article>
  );
}

const LOOKS = { 2: Terminal, 3: Dossier, 4: Blueprint, 5: Vault };

export default function TeaserCards({ t, style }) {
  const Look = LOOKS[style] || Terminal;
  return <Look t={t} />;
}
